+// OTHRYSTMJS: todoStore.mjs
+
+import { existsSync, readFileSync, writeFileSync, renameSync, mkdirSync, rmSync } from 'fs';
+import { join } from 'path';
+
+export function createTodoStore(filePath) {
+  const dirPath = join(filePath, '..');
+  const tempFilePath = join(dirPath, 'temp.todo');
+
+  function validateTodo(todo) {
+    if (!todo || typeof todo !== 'object') {
+      throw new Error('INVALID_TODO');
+    }
+
+    if (!todo.id || typeof todo.id !== 'string' || todo.id.trim() === '') {
+      throw new Error('INVALID_TODO');
+    }
+
+    if (!todo.text || typeof todo.text !== 'string' || todo.text.trim() === '') {
+      throw new Error('INVALID_TODO');
+    }
+
+    if (todo.done !== undefined && typeof todo.done !== 'boolean') {
+      throw new Error('INVALID_TODO');
+    }
+
+    return todo;
+  }
+
+  function validatePatch(patch) {
+    if (!patch || typeof patch !== 'object') {
+      throw new Error('INVALID_PATCH');
+    }
+
+    if (patch.text !== undefined && (typeof patch.text !== 'string' || patch.text.trim() === '')) {
+      throw new Error('INVALID_PATCH');
+    }
+
+    if (patch.done !== undefined && typeof patch.done !== 'boolean') {
+      throw new Error('INVALID_PATCH');
+    }
+
+    return patch;
+  }
+
+  function loadState() {
+    if (!existsSync(filePath)) {
+      return [];
+    }
+
+    try {
+      const data = readFileSync(filePath, 'utf-8');
+      const todos = JSON.parse(data);
+
+      if (!Array.isArray(todos)) {
+        throw new Error('STATE_CORRUPT');
+      }
+
+      return todos.map(todo => ({
+        id: todo.id,
+        text: todo.text.trim(),
+        done: todo.done !== undefined ? todo.done : false
+      }));
+    } catch (err) {
+      throw new Error('STATE_CORRUPT');
+    }
+  }
+
+  function saveState(state) {
+    try {
+      writeFileSync(tempFilePath, JSON.stringify(state, null, 2), 'utf-8');
+      renameSync(tempFilePath, filePath);
+    } catch (err) {
+      throw new Error('STATE_CORRUPT');
+    }
+  }
+
+  function getTodo(id) {
+    const state = loadState();
+    const todo = state.find(todo => todo.id === id);
+
+    if (!todo) {
+      throw new Error('NOT_FOUND');
+    }
+
+    return { ...todo };
+  }
+
+  function listTodos() {
+    const state = loadState();
+    return state.map(todo => ({ ...todo }));
+  }
+
+  function addTodo(todo) {
+    validateTodo(todo);
+
+    const state = loadState();
+    const existingTodo = state.find(t => t.id === todo.id);
+
+    if (existingTodo) {
+      throw new Error('DUPLICATE_ID');
+    }
+
+    state.push(todo);
+    saveState(state);
+
+    return { ...todo };
+  }
+
+  function updateTodo(id, patch) {
+    validatePatch(patch);
+
+    const state = loadState();
+    const todo = state.find(t => t.id === id);
+
+    if (!todo) {
+      throw new Error('NOT_FOUND');
+    }
+
+    if (patch.text !== undefined) {
+      todo.text = patch.text.trim();
+    }
+
+    if (patch.done !== undefined) {
+      todo.done = patch.done;
+    }
+
+    saveState(state);
+
+    return { ...todo };
+  }
+
+  function toggleTodo(id) {
+    const state = loadState();
+    const todo = state.find(t => t.id === id);
+
+    if (!todo) {
+      throw new Error('NOT_FOUND');
+    }
+
+    todo.done = !todo.done;
+    saveState(state);
+
+    return { ...todo };
+  }
+
+  function removeTodo(id) {
+    const state = loadState();
+    const todo = state.find(t => t.id === id);
+
+    if (!todo) {
+      throw new Error('NOT_FOUND');
+    }
+
+    const newState = state.filter(t => t.id !== id);
+    saveState(newState);
+
+    return { ...todo };
+  }
+
+  return {
+    list: listTodos,
+    get: getTodo,
+    add: addTodo,
+    update: updateTodo,
+    toggle: toggleTodo,
+    remove: removeTodo
+  };
+}

